// Package db is the server's SQLite store. Queries are generated by sqlc
// from schema.sql and queries/.
package db

import (
	"context"
	"database/sql"
	_ "embed" // For the schema.
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"time"
)

//go:generate sqlc generate

//go:embed schema.sql
var schema string

const busyTimeout = 5 * time.Second

// Client is the read-write store for devices, recipes, playlists, renders,
// and firmware.
//
// SQLite allows one writer at a time, and in WAL mode readers never wait on it.
// So every write goes through Writer, a single connection that callers queue
// for, and every read goes through Reader, a pool of read-only connections.
type Client struct {
	Writer *sql.DB
	Reader *sql.DB
	Write  *Queries
	Read   *Queries
}

// Open opens or creates the SQLite database at path.
// The parent directory is created mode 0750. The database file is mode 0600.
func Open(ctx context.Context, path string) (*Client, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return nil, fmt.Errorf("create state dir: %w", err)
	}

	// The writer opens first: it creates the file and switches it to WAL,
	// which the readers then inherit.
	writer, err := openPool(ctx, path, writerDSN(path, busyTimeout), 1)
	if err != nil {
		return nil, err
	}
	client := &Client{Writer: writer, Write: New(writer)}
	if err := client.applySchema(ctx); err != nil {
		_ = writer.Close()
		return nil, err
	}
	reader, err := openPool(ctx, path, readerDSN(path, busyTimeout), max(4, runtime.GOMAXPROCS(0)))
	if err != nil {
		_ = writer.Close()
		return nil, err
	}
	client.Reader, client.Read = reader, New(reader)
	if err := tighten(path); err != nil {
		_ = client.Close()
		return nil, err
	}
	return client, nil
}

func openPool(ctx context.Context, path, dsn string, conns int) (*sql.DB, error) {
	pool, err := sql.Open(driverName(), dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	pool.SetMaxOpenConns(conns)
	pool.SetMaxIdleConns(conns)
	if err := pool.PingContext(ctx); err != nil {
		_ = pool.Close()
		return nil, fmt.Errorf("ping sqlite %s: %w", path, err)
	}
	return pool, nil
}

func tighten(path string) error {
	if err := os.Chmod(path, 0o600); err != nil {
		return fmt.Errorf("chmod sqlite: %w", err)
	}
	for _, suffix := range []string{"-wal", "-shm"} {
		err := os.Chmod(path+suffix, 0o600)
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("chmod sqlite%s: %w", suffix, err)
		}
	}
	return nil
}

// InTx runs fn in a transaction on Writer, and commits it if fn returns nil.
// The transaction takes the write lock at BEGIN, so what fn reads through q
// stays true until it commits. fn must read through q, not Read, which cannot
// see the transaction's writes, and must not use Write, which waits for the
// one connection fn holds.
func (c *Client) InTx(ctx context.Context, fn func(q *Queries) error) error {
	tx, err := c.Writer.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback() }()
	if err := fn(c.Write.WithTx(tx)); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Close closes the database.
func (c *Client) Close() error {
	if c == nil {
		return nil
	}
	var errs []error
	if c.Reader != nil {
		errs = append(errs, c.Reader.Close())
	}
	if c.Writer != nil {
		errs = append(errs, c.Writer.Close())
	}
	return errors.Join(errs...)
}

// applySchema creates the schema in one transaction. Both drivers run every
// statement in a multi-statement Exec. This bypasses sqlc, which generates
// queries against the schema rather than applying it.
func (c *Client) applySchema(ctx context.Context) error {
	return c.InTx(ctx, func(q *Queries) error {
		if _, err := q.db.ExecContext(ctx, schema); err != nil {
			return fmt.Errorf("apply schema: %w", err)
		}
		return nil
	})
}
